comms.text:
@1 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@2 פַּקֵד יָת אַהֲרֹן וְיָת בְּנוֹהִי לְמֵימָר דָא אוֹרַיְתָא דַעֲלָתָא הִיא עֲלָתָא דְמִתּוֹקְדָא עַל מַדְבְּחָא כָל לֵילְיָא עַד צַפְרָא וְאֶשָׁתָא דְמַדְבְּחָא תְּהֵא יָקְדָא בֵהּ:
@3 וְיַלְבֵּשׁ כַּהֲנָא לְבוּשִׁין דְבוּץ וּמִכְנְסִין דְבוּץ יַלְבֵּשׁ עַל בִּסְרֵהּ וְיַפְרֵשׁ יָת קִטְמָא דִי תֵיכוּל אֶשָׁתָא יָת עֲלָתָא עַל מַדְבְּחָא וִישַׁוִנֵהּ בִּסְטַּר מַדְבְּחָא:
@4 וְיַשְׁלַח יָת לְבוּשׁוֹהִי וְיִלְבַּשׁ לְבוּשִׁין אָחֳרָנִין וְיַפֵּק יָת קִטְמָא לְמִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְכֵי:
@5 וְאֶשָׁתָא עַל מַדְבְּחָא תְהֵי יָקְדָא בֵהּ לָא תִטְּפֵי וְיַבְעַר עֲלַהּ כַּהֲנָא אָעַיָא בִּצְפַר בִּצְפָר וְיַסְדַר עֲלַהּ עֲלָתָא וְיַסֵק עֲלַהּ תַּרְבֵּי נִכְסַת קוּדְשַׁיָא:
@6 אֶשָׁתָא תְּדִירָא תְּהֵי יָקְדָא עַל מַדְבְּחָא לָא תִטְפֵי:
@7 וְדָא אוֹרַיְתָא דְמִנְחָתָא דִיקָרְבוּן יָתַהּ בְּנֵי אַהֲרֹן קֳדָם יְיָ לָקֳדָם מַדְבְּחָא:
@8 וְיַפְרֵשׁ מִנֵהּ בְּקֻמְצֵהּ מִסֻלְתָּא דְמִנְחָתָא וּמִמִשְׁחַהּ וְיָת כָּל לְבוּנְתָּא דִי עַל מִנְחָתָא וְיַסֵק לְמַדְבְּחָא לְאִתְקַבָּלָא בְרַעֲוָא אַדְכַּרְתָּא קֳדָם יְיָ:
@9 וּדְאִשְׁתָּאַר מִנַהּ יֵכְלוּן אַהֲרֹן וּבְנוֹהִי פַּטִיר תִּתְאַכֵל בַּאֲתַר קַדִּישׁ בְּדָרַת מַשְׁכַּן זִמְנָא יֵכְלֻנַהּ:
@10 לָא תִתְאֲפֵי חֲמִיעַ חָלָקְהוֹן יְהָבִית יָתַהּ מִקֻרְבָּנָי קֹדֶשׁ קוּדְשִׁין הִיא כְּחַטָאתָא וְכַאֲשָׁמָא:
@11 כָּל דְכוּרָא בִּבְנֵי אַהֲרֹן יֵכְלֻנַהּ קְיָם עָלָם לְדָרָתֵיכוֹן מִקֻרָבָּנַיָא דַיְיָ כֹּל דְיִקְרַב בְּהוֹן יִתְקַדָּשׁ:
@12 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@13 דֵין קֻרְבַּן אַהֲרֹן וּבְנוֹהִי דִי יְקָרְבוּן קֳדָם יְיָ בְּיוֹמָא דְרַבִּיאוּ יָתֵהּ חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא מִנְחָתָא תְּדִירָא פַּלְגוּתַהּ בְּצַפְרָא וּפַלְגוּתַהּ בְּרַמְשָׁא:
@14 עַל מַסְרֵיתָא בִּמְשַׁח תִּתְעֲבֵד רְבִיכָא תַיְתִנַהּ תּוּפִינֵי מִנְחַת בִּצוּעִין תְּקָרֵב לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@15 וְכַהֲנָא דִמְרַבָּא תְחוֹתוֹהִי מִבְּנוֹהִי יַעְבֵּד יָתַהּ קְיָם עָלָם קֳדָם יְיָ גְמִיר תִּתַּסָק:
@16 וְכָל מִנְחָתָא דְכַהֲנָא גְמִיר תְּהֵי לָא תִתְאֲכֵל:
@17 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@18 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי לְמֵימָר דָא אוֹרַיְתָא דְחַטָאתָא בַּאֲתַר דִי תִתְנְכֵס עֲלָתָא תִּתְנְכֵס חַטָאתָא קֳדָם יְיָ קֹדֶשׁ קוּדְשִׁין הִיא:
@19 כַּהֲנָא דִמְכַפֵּר בִּדְמַהּ יֵיכְלִנַהּ בַּאֲתַר קַדִישׁ תִּתְאֲכֵל בְּדָרַת מַשְׁכַּן זִמְנָא:
@20 כֹּל דִי יִקְרַב בְּבִסְרַהּ יִתְקַדַשׁ וְדִי יַדִי מִדְמַהּ עַל לְבוּשׁ דִי יַדִי עֲלַהּ תִּתְחַוָר בַּאֲתַר קַדִישׁ:
@21 וּמָן דַחֲסַף דִי תִתְבַּשֵׁל בֵּהּ יִתָּבָר וְאִם בְּמָנָא דִנְחָשָׁא תִּתְבַּשֵׁל וְיִתְמְרֵק וְיִשְׁתַּטֵף בְּמַיָא:
@22 כָּל דְכוּרָא בְּכַהֲנַיָא יֵכוּל יָתַהּ קֹדֶשׁ קוּדְשִׁין הִיא:
@23 וְכָל חַטָאתָא דִי יִתָּעַלּ מִדְמַהּ לְמַשְׁכַּן זִמְנָא לְכַפָּרָא בְקוּדְשָׁא לָא תִתְאֲכֵל בְּנוּרָא תִּתּוֹקָד:
@24 וְדָא אוֹרַיְתָא דַאֲשָׁמָא קֹדֶשׁ קוּדְשִׁין הוּא:
@25 בְּאַתְרָא דִי יִכְּסוּן יָת עֲלָתָא יִכְּסוּן יָת אֲשָׁמָא וְיָת דְמֵהּ יִזְרַק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@26 וְיָת כָּל תַּרְבֵּהּ יַפְרֵשׁ מִנֵהּ יָת אֲלִיתָא וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא:
@27 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חִצְרָא דְעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@28 וְיַסֵיק יָתְהוֹן כַּהֲנָא לְמַדְבְּחָא קוּרְבָּנָא קֳדָם יְיָ אֲשָׁמָא הוּא:
@29 כָּל דְכוּרָא בְּכַהֲנַיָא יֵיכְלִנֵהּ בַּאֲתַר קַדִישׁ יִתְאֲכָל קוֹדֶשׁ קוּדְשִׁין הוּא:
@30 כְּחַטָאתָא כַּאֲשָׁמָא אוֹרַיְתָא חֲדָא לְהוֹן כַּהֲנָא דִי יְכַפֵּר בֵּהּ דִילֵהּ יְהֵי:
@31 וְכַהֲנָא דִמְקָרֵב יַת עֲלַת גְבַר מְשַׁךְ עֲלָתָא דִי יְקָרֵב לְכַהֲנָא דִילֵהּ יְהֵי:
@32 וְכָל מִנְחָתָא דִי תִתְאֲפֵי בְּתַנוּרָא וְכָל דְתִתְעֲבֵד בְּרִדְתָּא וְעַל מַסְרֵיתָא לְכַהֲנָא דִמְקָרֵב יָתַהּ דִילֵהּ תְּהֵי:
@33 וְכָל מִנְחָתָא דְפִילָא בִמְשַׁח וּדְלָא פִילָא לְכָל בְּנֵי אַהֲרֹן תְּהֵי גְבַר כַּאָחוֹהִי:
@34 וְדָא אוֹרַיְתָא דְנִכְסַת קוּדְשַׁיָא דִי יְקָרֵב קֳדָם יְיָ:
@35 אִם עַל תּוֹדְתָא יְקָרְבִנֵהּ וִיקָרֵב עַל נִכְסַת תּוֹדְתָא גְרִיצָן פַּטִירָן דְפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִירִין דִּמְשִׁיחִין בִּמְשָׁח וְסוּלְתָּא רְבִיכָא גְרִיצָן דְפִילָן בִּמְשָׁח:
@36 עַל גְּרִיצָן דִלְחֵם חָמִיעַ יְקָרֵב קוּרְבָּנֵיהּ עַל נִכְסַת תּוֹדַת קוּדְשׁוֹהִי:
@37 וִיקָרֵב מִנֵהּ חַד מִכָּל קוּרְבַּן אַפְרָשׁוּתָא קֳדָם יְיָ לְכַהֲנָא דְיִזְרַק יָת דַם נִכְסַת קוּדְשַׁיָא דִילֵהּ יְהֵי:
@38 וּבְשַׂר נִכְסַת תּוֹדַת קוּדְשׁוֹהִי בְּיוֹם קֻרְבָּנֵהּ יִתְאֲכֵל לָא יַצְנַע מִנֵהּ עַד צַפְרָא:
@39 וְאִם נִדְרָא אוֹ נְדַבְתָּא נִכְסַת קֻרְבָּנֵהּ בְּיוֹמָא דִי יְקָרֵב יָת נִכְסְתֵיהּ יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר מִנֵהּ יִתְאֲכֵלּ:
@40 וּדְאִשְׁתָּאַר מִבְּסַר נִכְסָתָא בְּיוֹמָא תְּלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@41 וְאִם אִתְאֲכָלָא יִתְאֲכֵל מִבְּסַר נִכְסַת קוּדְשׁוֹהִי בְּיוֹמָא תְּלִיתָאָה לָא יְהֵי לְרַעֲוָא דִמְקָרֵב יָתֵהּ לָא יִתְחַשֵׁב לֵהּ מְרָחָק יְהֵי וֶאֱנַשׁ דְתֵכוּל מִנֵהּ חוֹבֵהּ יְקַבֵּל:
@42 וּבְסַר קוּדְשָׁא דִי יִקְרַב בְּכָל מְסָאָב לָא יִתְאֲכֵל בְּנוּרָא יִתּוֹקָד וּבְסַר קוּדְשָׁא כָּל דִי דְכֵי לְקוּדְשָׁא יֵיכוּל בְּסַר קוּדְשָׁא:
@43 וֶאֱנַשׁ דִי תֵכוּל בִּסְרָא מִנִכְסַת קוּדְשַׁיָא דִי קֳדָם יְיָ וְסוֹבְתֵהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַּהּ:
@44 וֶאֱנַשׁ אֲרֵי תִקְרַב בְּכָל מְסָאָב בְסוֹאֲבַת אֱנָשָׁא אוֹ בִּבְעִירָא מְסָאֲבָא אוֹ בְּכָל שִׁקְצָא מְסָאָב וְיֵיכוּל מִבְּסַר נִכְסַת קוּדְשַׁיָא דִי קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַּהּ:
@45 וּמַלֵיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@46 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר כָּל תְּרַב תּוֹר וְאִמַר וְעִזָא לָא תֵיכְלוּן:
@47 וּתְרַב נְבִילָא וּתְרַב תְּבִירָא יִתְעֲבֵד לְכָל עִבִדְתָּא וּמֵיכַל לָא תֵיכְלוּנֵהּ:
@48 אֲרֵי כָל דְיֵכוּל תַּרְבָּא מִן בְּעִירָא דִי יִקָרְבוּן מִנַהּ קוּרְבָּנָא קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא דִי תֵיכוּל מֵעַמַּהּ:
@49 וְכָל דְמָא לָא תֵיכְלוּן בְּכֹל מוֹתְבָנֵיכוֹן דְעוֹפָא וְדִבְעִירָא:
@50 כָּל אֱנָשָׁא דִי תֵיכוּל כָּל דְמָא וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַהּ:
@51 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@52 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר דִמְקָרֵב יָת נִכְסַת קוּדְשׁוֹהִי קֳדָם יְיָ יַיְתִי יָת קֻרְבָּנֵהּ לָקֳדָם יְיָ מִנִכְסַת קוּדְשׁוֹהִי:
@53 יְדוֹהִי תַיְתוּן יָת קֻרְבָּנַיָא דַיְיָ יָת תַּרְבָּא עַל חַדְיָא יַיְתִנֵהּ יָת חֶדְיָא לַאֲרָמָא יָתֵהּ אֲרוּמָא קֳדָם יְיָ:
@54 וְיַסֵק כַּהֲנָא יָת תַּרְבָּא לְמַדְבְּחָא וִיהֵי חֶדְיָא לְאַהֲרֹן וְלִבְנוֹהִי:
@55 וְיָת שׁוֹקָא דְיַמִינָא תִּתְּנוּן אַפְרָשׁוּתָא לְכַהֲנָא מִנִכְסַת קוּדְשֵׁיכוֹן:
@56 דִמְקָרֵב יָת דָם נִכְסַת קוּדְשַׁיָא וְיָת תַּרְבָּא מִבְּנֵי אַהֲרֹן דִילֵהּ תְּהֵי שׁוֹקָא דְיַמִינָא לָחֳלָק:
@57 אֲרֵי יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא נְסֵבִית מִן בְּנֵי יִשְׂרָאֵל מִנִכְסַת קוּדְשֵׁיהוֹן וִיהָבִית יָתְהוֹן לְאַהֲרֹן כַּהֲנָא וְלִבְנוֹהִי לִקְיָם עָלָם מִן בְּנֵי יִשְׂרָאֵל:
@58 דָא רְבוּת אַהֲרֹן וּרְבוּת בְּנוֹהִי מִקוּרְבָּנַיָא דַיְיָ בְּיוֹמָא דְקָרֵב יָתְהוֹן לְשַׁמָשָׁא קֳדָם יְיָ:
@59 דִי פַקִיד יְיָ לְמִתַּן לְהוֹן בְּיוֹמָא דְרַבִּי יָתְהוֹן מִן בְּנֵי יִשְׂרָאֵל קְיָם עָלָם לְדָרֵיהוֹן:
@60 דָא אוֹרַיְתָא לַעֲלָתָא לְמִנְחָתָא וּלְחַטָּאתָא וְלַאֲשָׁמָא וּלְקוּרְבָּנַיָא וּלְנִכְסַת קוּדְשַׁיָא:
@61 דִי פַקִיד יְיָ יָת מֹשֶׁה בְּטוּרָא דְסִינָי בְּיוֹמָא דְפַקְדֵהּ יָת בְּנֵי יִשְׂרָאֵל לְקָרָבָא יָת קֻרְבָּנְהוֹן קֳדָם יְיָ בְּמַדְבְּרָא דְסִינָי:
@62 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@63 קָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי עִמֵהּ וְיָת לְבוּשַׁיָא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת תּוֹרָא דְחַטָאתָא וְיָת תְּרֵין דִכְרִין וְיָת סַלָא דְפַטִירַיָא:
@64 וְיָת כָּל כְּנִשְׁתָּא כְּנֵשׁ לִתְרַע מַשְׁכַּן זִמְנָא:
@65 וַעֲבַד מֹשֶׁה כְּמָא דִי פַקִיד יְיָ יָתֵהּ וְאִתְכְּנִשַׁת כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא:
@66 וַאֲמַר מֹשֶׁה לִכְנִשְׁתָּא דֵין פִּתְגָמָא דִי פַקִיד יְיָ לְמֶעְבָּד:
@67 וְקָרִיב מֹשֶׁה יָת אַהֲרֹן וְיָת בְּנוֹהִי וְאַסְחֵי יָתְהוֹן בְּמַיָא:
@68 וִיהַב עֲלוֹהִי יָת כִּתּוּנָא וְזָרֵז יָתֵהּ בְּהֶמְיָנָא וְאַלְבֵּשׁ יָתֵהּ יָת מְעִילָא וִיהַב עֲלוֹהִי יָת אֵפוֹדָא וְזָרֵז יָתֵהּ בְּהֶמְיַן אֵפוֹדָא וְאַתְקֵן לֵהּ בֵּהּ:
@69 וְשַׁוִי עֲלוֹהִי יָת חוּשְׁנָא וִיהַב בְּחוּשְׁנָא יָת אוּרַיָא וְיָת תֻּמַיָא:
@70 וְשַׁוִי יָת מִצְנַפְתָּא עַל רֵישֵׁיהּ וְשַׁוִי עַל מִצְנֶפְתָּא לָקֳבֵיל אַפּוֹהִי יָת צִיצָא דְדַהֲבָא כְּלִילָא דְקוּדְשָׁא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@71 וּנְסִיב מֹשֶׁה יָתּ מִשְׁחָא דִרְבוּתָא וְרַבִּי יָת מַשְׁכְּנָא וְיָת כָּל דִי בֵהּ וְקַדִישׁ יָתְהוֹן:
@72 וְאַדִי מִנֵהּ עַל מַדְבְּחָא שְׁבַע זִמְנִין וְרַבִּי יָת מַדְבְּחָא וְיָת כָּל מָנוֹהִי וְיָת כִּיוֹרָא וְיָת בְּסִיסֵהּ לְקַדָשׁוּתְהוֹן:
@73 וַאֲרֵיק מִמִשְׁחָא דִרְבוּתָא עַל רֵישָׁא דְאַהֲרֹן וְרַבִּי יָתֵהּ לְקַדָשׁוּתֵהּ:
@74 וְקָרִיב מֹשֶׁה יָת בְּנֵי אַהֲרֹן וְאַלְבֵּשִׁנוּן כִּתּוּנִין וְזָרֵז יָתְהוֹן הֶמְיָנִין וְאַתְקֵן לְהוֹן כּוֹבָעִין כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@75 וְקָרֵב יָת תּוֹרָא דְחַטָאתָא וּסְמַךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא דְחַטָאתָא:
@76 וּנְכֵס וּנְסִיב מֹשֶׁה יָת דְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר בְּאֶצְבְּעֵהּ וְדַכִּי יָת מַדְבְּחָא וְיָת דְמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא וְקַדְשֵׁהּ לְכַפָּרָא עֲלוֹהִי:
@77 וּנְסִיב יָת כָּל תַּרְבָּא דִי עַל גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְאַסֵק מֹשֶׁה לְמַדְבְּחָא:
@78 וְיָת תּוֹרָא וְיָת מַשְׁכֵהּ וְיָת בִּסְרֵהּ וְיָת אָכְלֵהּ אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@79 וְקָרִיב יָת דִכְרָא דַעֲלָתָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@80 וּנְכֵס וּזְרַק מֹשֶׁה יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@81 וְיָת דִכְרָא פַּלֵג לְאֶבְרוֹהִי וְאַסֵק מֹשֶׁה יָת רֵישָׁא וְיָת אֶבְרַיָא וְיָת תַּרְבָּא:
@82 וְיָת גַוָא וְיָת כְּרָעַיָא חַלִיל בְּמַיָא וְאַסֵק מֹשֶׁה יָת כָּל דִכְרָא לְמַדְבְּחָא עֲלָתָא הוּא לְאִתְקַבָּלָא בְרַעִוָא קוּרְבָּנָא הוּא קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@83 וְקָרִיב יָת דִכְרָא תִנְיָנָא דְכַר קוּרְבָּנַיָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@84 וּנְכֵס וּנְסִיב מֹשֶׁה מִן דְמָא וִיהַב עַל רוּם אוּדְנָא דְאַהֲרֹן דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא:
@85 וְקָרֵיב יָת בְּנֵי אַהֲרֹן וִיהַב מֹשֶׁה מִן דְמָא עַל רוּם אוּדְנֵהוֹן דְיַמִינָא וְעַל אִלְיוֹן אוּדְנֵהוֹן דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵיהוֹן דְיַמִינָא וּזְרַק מֹשֶׁה יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@86 וּנְסִיב יָת תַּרְבָּא וְיָת אֲלִיתָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְיָת שׁוֹקָא דְיַמִינָא:
@87 וּמִסַלָא דְפַטִירַיָא דִי קֳדָם יְיָ נְסִיב גְרִצְתָּא פַטִירָא חֲדָא וּגְרִיצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד וְשַׁוִי עַל תַּרְבַּיָא וְעַל שׁוֹקָא דְיַמִינָא:
@88 וִיהַב יָת כֹּלָא עַל יְדֵי אַהֲרֹן וְעַל יְדֵי בְנוֹהִי וַאֲרֵים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@89 וּנְסִיב מֹשֶׁה יָתְהוֹן מֵעַל יְדֵיהוֹן וְאַסֵק לְמַדְבְּחָא עַל עֲלָתָא קוּרְבָּנַיָא אִנוּן לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא הוּא קֳדָם יְיָ:
@90 וּנְסִיב מֹשֶׁה יָת חֶדְיָא וַאֲרִימֵהּ אֲרָמָא קֳדָם יְיָ מִדְכַר קוּרְבָּנַיָא לְמֹשֶׁה הֲוָה לָחֳלָק כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@91 וּנְסִיב מֹשֶׁה מִמִשְׁחָא דִרְבוּתָא וּמִן דְמָא דִי עַל מַדְבְּחָא וְאַדִי עַל אַהֲרֹן עַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵהּ וְקַדִישׁ יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְיָת בְּנוֹהִי וְיָת לְבוּשֵׁי בְנוֹהִי עִמֵהּ:
@92 וַאֲמַר מֹשֶׁה לְאַהֲרֹן וְלִבְנוֹהִי בַּשִׁילוּ יָת בִּסְרָא בִּתְרַע מַשְׁכַּן זִמְנָא וְתַמָן תֵּיכְלוּן יָתֵהּ וְיָת לַחְמָא דִי בְּסַל קוּרְבָּנַיָא כְּמָא דִי פַקֵדִית לְמֵימָר אַהֲרֹן וּבְנוֹהִי יֵיכְלוּנֵהּ:
@93 וּדְאִשְׁתָּאַר בְּבִשְׂרָא וּבְלַחְמָא בְּנוּרָא תּוֹקְדוּן:
@94 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְּקוּן שִׁבְעָא יוֹמִין עַד יוֹם מִשְׁלַם יוֹמֵי קוּרְבָּנֵיכוֹן אֲרֵי שִׁבְעָא יוֹמִין יְקָרֵב יָת קֻרְבָּנֵיכוֹן:
@95 כְּמָא דִי עֲבַד בְּיוֹמָא הָדֵין פָּקִיד יְיָ לְמֶעְבַּד לְכַפָּרָא עֲלֵיכוֹן:
@96 וּבִתְרַע מַשְׁכַּן זִמְנָא תֵּיתְבוּן יְמָם וְלֵילֵי שִׁבְעָא יוֹמִין וְתִטְרוּן יָת מַטְרַת מֵימְרָא דַיְיָ וְלָא תְמוּתוּן אֲרֵי כֵן אִתְפַּקָדִית:
@97 וַעֲבַד אַהֲרֹן וּבְנוֹהִי יָת כָּל פִּתְגָמַיָא דִי פַקִיד יְיָ בִּידָא דְמֹשֶׁה: פפפ:

@2 **צו את אהרן.** אין צו אלא לשון זרוז מיד ולדורות. אמר ר' שמעון ביותר צריך הכתוב לזרז במקום שיש בו חסרון כיס: **זאת תורת העלה** וגו' **.** הרי הענין הזה בא ללמד על הקטר חלבים ואיברים שיהא כשר כל הלילה, וללמד על הפסולין איזה אם עלה ירד, ואיזה אם עלה לא ירד, שכל תורה לרבות הוא בא, לומר תורה אחת לכל העולים, ואפלו פסולין, שאם עלו לא ירדו: **הוא העלה.** למעט את הרובע ואת הנרבע וכיוצא בהן, שלא היה פסולן בקדש, שנפסלו קודם שבאו לעזרה:
@3 **מדו בד.** היא הכתנת. ומה תלמוד לומר מדו, שתהא כמדתו: **על בשרו.** שלא יהא דבר חוצץ בנתים: **והרים את הדשן.** היה חותה מלא מחתה מן המאכלות הפנימיות ונותנן במזרחו של כבש: **הדשן אשר תאכל האש את העלה.** ועשאתה דשן, מאותו דשן ירים תרומה ושמו אצל המזבח: **על המזבח.** מצא אברים שעדין לא נתעכלו, מחזירן על המזבח, לאחר שחתה גחלים אלך ואלך ונטל מן הפנימיות, שנאמר את העלה על המזבח:
@4 **ופשט את בגדיו.** אין זו חובה אלא דרך ארץ, שלא ילכלך בהוצאת הדשן בגדים שהוא משמש בהן תמיד. בגדים שבשל בהן קדרה לרבו אל ימזג בהן כוס לרבו, לכך ולבש בגדים אחרים פחותין מהן: **והוציא את הדשן.** הצבור בתפוח, כשהוא רבה ואין מקום למערכה, מוציאו משם. ואין זה חובה בכל יום, אבל התרומה חובה בכל יום ה **והאש על המזבח תוקד בו.** רבה כאן יקידות הרבה על מוקדה, ואש המזבח תוקד בו, והאש על המזבח תוקד בו, אש תמיד תוקד על המזבח, כלן נדרשו במסכת יומא (מג ב) שנחלקו רבותינו במנין המערכות שהיו שם: **וערך עליה העלה.** עולת תמיד היא תקדים: **חלבי השלמים.** אם יביאו שם שלמים. ורבותינו למדו מכאן עליה, על עולת הבקר השלם כל הקרבנות כלם. מכאן שלא יהא דבר מאוחר לתמיד של בין הערבים:
@6 **אש תמיד.** אש שנאמר בה תמיד, היא שמדליקין בה את הנרות, שנאמר בה (שמות כז כ) להעלות נר תמיד, אף היא מעל המזבח החיצון תוקד: **לא תכבה.** המכבה אש על המזבח עובר בשני לאוין:
@7 **וזאת תורת המנחה.** תורה אחת לכלן להטעינן שמן ולבונה האמורין בענין. שיכול אין לי טעונות שמן ולבונה אלא מנחת ישראל שהיא נקמצת, מנחת כהנים שהיא כליל מנין, תלמוד לומר תורת: **הקרב אתה.** היא הגשה בקרן מערבית דרומית: **לפני ה'.** הוא מערב שהוא לצד אהל מועד: **אל פני המזבח.** הוא הדרום, שהוא פניו של מזבח, שהכבש נתון לאותו הרוח:
@8 **והרים ממנו.** מהמחבר, שיהא עשרון שלם בבת אחת בשעת קמיצה: **בקמצו.** שלא יעשה מדה לקומץ: **מסלת המנחה ומשמנה.** מכאן שקומץ ממקום שנתרבה שמנה: **המנחה.** שלא תהא מעורבת באחרת: **ואת כל הלבנה אשר על המנחה והקטיר.** שמלקט את לבונתה לאחר קמיצה ומקטירו. ולפי שלא פרש כן אלא באחת מן המנחות בויקרא (ב, א. ג) , הצרך לשנות פרשה זו, לכלול כל המנחות כמשפטן:
@9 **במקום קדש.** ואיזהו, בחצר אהל מועד:
@10 **לא תאפה חמץ חלקם.** אף השירים אסורים בחמץ: **כחטאת וכאשם.** מנחת חוטא הרי היא כחטאת, לפיכך קמצה שלא לשמה פסולה. מנחת נדבה הרי היא כאשם, לפיכך קמצה שלא לשמה כשרה:
@11 **כל זכר.** אפלו בעל מום. למה נאמר, אם לאכילה הרי כבר אמור לחם אלהיו מקדשי הקדשים וגו' , אלא לרבות בעלי מומין למחלוקת: **כל אשר יגע** וגו' **.** קדשים קלים או חלין שיגעו בה ויבלעו ממנה: **יקדש.** להיות כמוה, שאם פסולה יפסלו, ואם כשרה יאכלו כחמר המנחה:
@13 **זה קרבן אהרן ובניו.** אף ההדיוטות מקריבין עשירית האיפה ביום שהן מתחנכין לעבודה, אבל כהן גדול בכל יום, שנאמר מנחה תמיד וגו' והכהן המשיח תחתיו מבניו וגו' חק עולם וגו' (פסוק טו) יד **מרבכת.** חלוטה ברותחין כל צרכה: **תפיני.** אפויה אפיות הרבה, שאחר חליטתה אופה בתנור וחוזר ומטגנה במחבת: **מנחת פתים.** מלמד שטעונה פתיתה:
@15 **המשיח תחתיו מבניו.** המשיח מבניו תחתיו: **כליל תקטר.** אין נקמצת להיות שיריה נאכלין אלא כלה כליל, וכן כל מנחת כהן של נדבה כליל תהיה טז **כליל.** כלה שוה לגבוה:
@19 **המחטא אתה.** העובד עבודותיה שהיא נעשית חטאת על ידו: **המחטא אתה יאכלנה.** הראוי לעבודה, יצא טמא בשעת זריקת דמים שאינו חולק בבשר, ואי אפשר לומר שאוסר שאר כהנים באכילתה חוץ מן הזורק דמה, שהרי נאמר למטה (פסוק כב) כל זכר בכהנים יאכל אתה:
@20 **כל אשר יגע בבשרה.** כל דבר אוכל אשר יגע ויבלע ממנה: **יקדש.** להיות כמוה, אם פסולה תפסל, ואם היא כשרה תאכל כחמר שבה: **ואשר יזה מדמה על הבגד.** ואם הזה מדמה על הבגד, אותו מקום דם הבגד אשר יזה עליה, תכבס בתוך העזרה: **אשר יזה.** יהא נזה, כמו (איוב טו כט) ולא יטה לארץ מנלם, יהא נטוי:
@21 **ישבר.** לפי שהבליעה שנבלעת בו נעשה נותר, והוא הדין לכל הקדשים: **ומרק.** לשון תמרוקי הנשים (אסתר ב יב) אישקורימינ''ט בלע''ז [נקוי] : **ומרק ושטף.** לפלוט את בליעתו, אבל כלי חרס למדך הכתוב כאן שאינו יוצא מידי דפיו לעולם:
@22 **כל זכר בכהנים יאכל אתה.** הא למדת שהמחטא אותה האמור למעלה לא להוציא שאר הכהנים, אלא להוציא את שאינו ראוי לחטוי:
@23 **וכל חטאת** וגו' **.** שאם הכניס מדם חטאת החיצונה לפנים פסולה: **וכל.** לרבות שאר קדשים:
@24 **קדש קדשים הוא.** הוא קרב ואין תמורתו קרבה:
@25 **ישחטו.** רבה לנו שחיטות הרבה, לפי שמצינו אשם בצבור, נאמר ישחטו רבים. ותלאו בעולה להביא עולת צבור לצפון:
@26 **ואת כל חלבו** וגו' **.** עד כאן לא נתפרשו אמורין באשם, לכך הצרך לפרשם כאן, אבל חטאת כבר נתפרשו בה בפרשת ויקרא (פרק ב) : **את האליה.** לפי שאשם אינו בא אלא איל או כבש, ואיל וכבש נתרבו באליה:
@28 **אשם הוא.** עד שינתק שמו ממנו. למד על אשם שמתו בעליו או שנתכפרו בעליו, אף על פי שעומד להיות דמיו עולה לקיץ המזבח, אם שחטו סתם, אינו כשר לעולה קודם שנתק לרעיה. ואינו בא ללמד על האשם שיהא פסול שלא לשמו, כמו שדרשו הוא, הכתוב בחטאת, לפי שאשם לא נאמר בו אשם הוא, אלא לאחר הקטרת אמורין, והוא עצמו שלא הקטרו אמוריו כשר:
@29 **קדש קדשים הוא.** בתורת כהנים הוא נדרש:
@30 **תורה אחת להם.** בדבר זה: **הכהן אשר יכפר בו.** הראוי לכפרה חולק בו, פרט לטבול יום ומחסר כפורים ואונן:
@31 **עור העלה אשר הקריב לכהן לו יהיה.** פרט לטבול יום ומחסר כפורים ואונן שאינן חולקים בעורות:
@32 **לכהן המקריב אתה** וגו' **.** יכול לו לבדו, תלמוד לומר לכל בני אהרן תהיה. יכול לכלן, תלמוד לומר לכהן המקריב, הא כיצד לבית אב של אותו יום שמקריבין אותה:
@33 **בלולה בשמן.** זו מנחת נדבה: **וחרבה.** זו מנחת חוטא ומנחת קנאות שאין בהן שמן:
@35 **אם על תודה יקריבנו.** אם על דבר הודאה על נס שנעשה לו, כגון יורדי הים והולכי מדברות וחבושי בית האסורים וחולה שנתרפא שהם צריכין להודות שכתוב בהן (תהלים קז כא. כב) יודו לה' חסדו ונפלאותיו לבני אדם ויזבחו זבחי תודה. אם על אחת מאלה נדר שלמים הללו, שלמי תודה הן, וטעונות לחם האמור בענין, ואינן נאכלין אלא ליום ולילה, כמו שמפורש כאן: **והקריב על זבח התודה.** ארבעה מיני לחם חלות, ורקיקין, ורבוכה, שלשה מיני מצה, וכתיב (פסוק יג) על חלת לחם חמץ וגו' , וכל מין ומין עשר חלות, כך מפורש במנחות (עז א) . ושעורן חמש סאין ירושלמיות שהן שש מדבריות, עשרים עשרון: **מרבכת.** לחם חלוט ברותחין כל צרכו יג **יקריב קרבנו על זבח.** מגיד שאין הלחם קדוש קדשת הגוף להפסל ביוצא וטבול יום ומלצאת לחלין בפדיון, עד שישחט הזבח:
@37 **אחד מכל קרבן.** לחם אחד מכל מין ומין יטול תרומה לכהן העובד עבודתה, והשאר נאכל לבעלים ובשרה לבעלים, חוץ מחזה ושוק שבה, כמו שמפורש למטה (פסוקים כט. לב) תנופת חזה ושוק בשלמים. והתודה קרויה שלמים:
@38 **ובשר זבח תודת שלמיו.** יש כאן רבויין הרבה, לרבות חטאת ואשם ואיל נזיר וחגיגת ארבעה עשר, שיהיו נאכלין ליום ולילה: **ביום קרבנו יאכל.** וכזמן בשרה זמן לחמה: **לא יניח ממנו עד בקר.** אבל אוכל הוא כל הלילה, אם כן למה אמרו עד חצות, כדי להרחיק אדם מן העברה:
@39 **ואם נדר או נדבה.** שלא הביאה על הודאה של נס, אינה טעונה לחם ונאכלת לשני ימים, כמו שמפורש בענין: **וממחרת והנותר ממנו.** בראשון יאכל. וי''ו זו יתרה היא, ויש כמוה הרבה במקרא, כגון (בראשית לו כד) ואלה בני צבעון ואיה וענה, (דניאל ח יג) תת וקדש וצבא מרמס:
@41 **ואם האכל יאכל** וגו' **.** במחשב בשחיטה לאכלו בשלישי הכתוב מדבר. יכול אם אכל ממנו בשלישי יפסל למפרע, תלמוד לומר המקריב אותו לא יחשב, בשעת הקרבה הוא נפסל, ואינו נפסל בשלישי. וכן פרושו בשעת הקרבתו לא תעלה זאת במחשבה, ואם חשב פגול יהיה: **והנפש האכלת ממנו.** אפלו בתוך הזמן עונה תשא:
@42 **והבשר.** של קדש שלמים אשר יגע בכל טמא לא יאכל: **והבשר.** לרבות אבר שיצא מקצתו, שהפנימי מתר: **כל טהור יאכל בשר.** מה תלמוד לומר, לפי שנאמר (דברים יב כז) ודם זבחיך ישפך וגו' והבשר תאכל, יכול לא יאכלו שלמים אלא הבעלים, לכך נאמר כל טהור יאכל בשר: **והבשר כל טהור יאכל בשר.** כלומר כל מה שאסרתי לך בחטאת ואשם, שאם יצאו חוץ לקלעם אסורין, כמו שכתוב (ו ט) בחצר אהל מועד יאכלוה, בבשר זה אני אומר לך כל טהור יאכל בשר אפלו בכל העיר:
@43 **וטמאתו עליו.** בטמאת הגוף הכתוב מדבר, אבל טהור שאכל את הטמא, אינו ענוש כרת, אלא באזהרה והבשר אשר יגע בכל טמא וגו' (פסוק יט) . ואזהרת טמא שאכל את הטהור אינה מפורשת בתורה, אלא חכמים למדוה בגזרה שוה. שלש כריתות אמורות באוכלי קדשים בטמאת הגוף, ודרשוה רבותינו בשבועות (ז א) אחת לכלל ואחת לפרט ואחת ללמד על קרבן עולה ויורד, שלא נאמר אלא על טמאת מקדש וקדשיו:
@47 **יעשה לכל מלאכה.** בא ולמד על החלב שאינו מטמא טמאת נבלות: **ואכל לא תאכלהו.** אמרה תורה יבוא אסור נבלה וטרפה ויחול על אסור חלב, שאם אכלו, יתחיב אף על לאו של נבלה, ולא תאמר אין אסור חל על אסור:
@49 **בכל מושבתיכם.** לפי שהיא חובת הגוף ואינה חובת קרקע, נוהגת בכל מושבות, ובמסכת קדושין בפרק א' (לז א) מפרש למה הצרך לומר: **לעוף ולבהמה.** פרט לדם דגים וחגבים:
@53 **ידיו תביאינה** וגו' **.** שתהא יד הבעלים מלמעלה והחלב והחזות נתונין בה, ויד כהן מלמטה ומניפן: **את אשי ה'.** ומה הן האשים, **את החלב על החזה יביאנו.** כשמביאו מבית המטבחים נותן החלב על החזה, וכשנותנו ליד הכהן המניף נמצא החזה למעלה והחלב למטה, וזהו האמור במקום אחר (ויק' י טו) שוק התרומה וחזה התנופה על אשי החלבים יביאו להניף וגו' , ולאחר התנופה נותנו לכהן המקטיר, ונמצא החזה למטה, וזהו שנאמר (ויק' ט כ) וישימו את החלבים על החזות ויקטר החלבים המזבחה. למדנו ששלשה כהנים זקוקין לה, כך מפורש במנחות (סב א) : **את החלב על החזה יביאנו.** ואת החזה למה מביא, להניף אותו הוא מביאו, ולא שיהא הוא מן האשים. לפי שנאמר את אשי ה' את החלב על החזה, יכול שיהא אף החזה לאשים, לכך נאמר את החזה להניף וגו' :
@54 **והקטיר הכהן את החלב.** ואחר כך והיה החזה לאהרן, למדנו שאין הבשר נאכל בעוד שהאמורים למטה מן המזבח:
@55 **שוק.** מן הפרק של ארכבה הנמכרת עם הראש עד הפרק האמצעי, שהוא סובך של רגל:
@56 **המקריב את דם השלמים** וגו' **.** מי שהוא ראוי לזריקתו ולהקטיר חלבו, יצא טמא בשעת זריקת דמים או בשעת הקטר חלבים, שאינו חולק בבשר לד **התנופה' התרומה.** מוליך ומביא, מעלה ומוריד לז **ולמלואים.** ליום חנוך הכהנה:
@63 **קח את אהרן.** פרשה זו נאמרה שבעת ימים קודם הקמת המשכן, שאין מקדם ומאחר בתורה: **קח את אהרן.** קחנו בדברים ומשכהו: **ואת פר החטאת** וגו' **.** אלו האמורים בענין צואת המלואים בואתה תצוה, ועכשיו ביום ראשון למלואים חזר וזרזו בשעת מעשה:
@64 **הקהל אל פתח אהל מועד.** זה אחד מן המקומות שהחזיק מועט את המרבה:
@66 **זה הדבר.** דברים שתראו שאני עושה לפניכם צוני הקדוש ברוך הוא לעשות, ואל תאמרו לכבודי ולכבוד אחי אני עושה. כל הענין הזה פרשתי בואתה תצוה:
@69 **את האורים.** כתב של שם המפורש:
@70 **וישם על המצנפת.** פתילי תכלת הקבועים בציץ נתן על המצנפת, נמצא הציץ תלוי במצנפת:
@72 **ויז ממנו על המזבח.** לא ידעתי היכן נצטוה בהזאות הללו:
@73 **ויצק' וימשח.** בתחלה יוצק על ראשו, ואחר כך נותן בין ריסי עיניו ומושך באצבעו מזה לזה:
@74 **ויחבש.** לשון קשירה:
@76 **ויחטא את המזבח.** חטאו וטהרו מזרות להכנס לקדשה: **ויקדשהו.** בעבודה זו: **לכפר עליו.** מעתה כל הכפרות:
@77 **ואת יתרת הכבד.** על הכבד (שמות כט יג) לבד הכבד, שהיה נוטל מעט מן הכבד עמה:
@83 **איל המלאים.** איל השלמים, שמלואים לשון שלמים, שממלאים ומשלימים את הכהנים בכהנתם:
@87 **וחלת לחם שמן.** היא רבוכה, שהיה מרבה בה שמן כנגד החלות והרקיקין, כך מפורש במנחות (עח א) :
@89 **ויקטר המזבחה.** משה שמש כל שבעת ימי המלואים בחלוק לבן: **על העלה.** אחר העלה. ולא מצינו שוק של שלמים קרב בכל מקום חוץ מזה:
@95 **צוה ה' לעשת.** כל שבעת הימים. ורבותינו זכרונם לברכה דרשו לעשות. זה מעשה פרה. לכפר. זה מעשה יום הכפורים, וללמד שכהן גדול טעון פרישה קודם יום הכפורים שבעת ימים, וכן הכהן השורף את הפרה:
@96 **ולא תמותו.** הא אם לא תעשו כן, הרי אתם חיבים מיתה:
@97 **ויעש אהרן ובניו.** להגיד שבחן שלא הטו ימין ושמאל:

@2 **צו את אהרן**. אמרו ז''ל בתורת כהנים (עי' קידושין כט.) אין צו אלא זירוז מיד ולדורות, אמר רבי שמעון ביותר צריך הכתוב לזרז כל מקום שיש בו חסרון כיס, עד כאן. הנה לתנא קמא יש כאן זירוז, לצד מה שגדלו פרטי דיני העולה בלילה, מה שאין משפט דומה לה בכל הקרבנות, לזה זרזו מיד פירוש לאותו זמן יתנהג, כמו שלמדו בתורת כהנים מפרשת נרות דכתיב (להלן כד ב) צו את בני ישראל ויקחו אליך וגו' וכתיב (במדבר ח ג) ויעש כן אהרן, לדורות, פירוש שיתנהגו משפטי העולה ככתבן לדורות, שאמרו ז''ל (פסיקתא פסוק את קרבני לחמי במדבר כח ב) וז''ל לפי שהיו ישראל אומרים לשעבר היו המסעות נוהגים והתמידין נוהגים, פסקו המסעות פסקו התמידין, עד כאן:
@2 **הרי** שיש מקום לטעות שלא תנהוג לדורות, וחסרון כיס שאומר רבי שמעון רבו בו הפירושים, יש אומרים לאו דוקא חסרון כים, אלא הוא הדין ריבוי הצער, ויש אומרים כי היה בטל ממלאכתו כל הלילה, והוא חסרון כיס, ויש אומרים חסרון כיס הוא לישראל, שאברי עולה נשרפין על המזבח ואינם נהנין מהם, ויש אומרים חסרון כים לכהן, שהוא ירצה להקריב קרבנות אחרים שיש לו זכות בהם, מה שאין כן העולה שכולה כליל ואין לו בה אלא העור, וכל הדברים רחוקים בעיני:
@2 **ואולי** נראה שהוא על התמדת עצים שאמרו ז''ל (יומא מה.) ג' מערכות של אש היו שם וכו', שלישית אין עליה כלום, אלא לקיים אש תמיד תוקד וגו' עד כאן, על פרט זה אמר חסרון כים פירוש ללא דבר, שאין בו אחד מהקרבנות, אלא שתהיה האש אוכלת עצים כל הלילה, וגם הם שוים ממון:
@2 **עוד** נראה כי חסרון כיס הוא, לצד שמצות עולת תמיד עשה בה הכתוב דבר גדול, דכתיב (להלן פסוק ה) ובער עליה הכהן וגו' וערך עליה העולה, ותנו רבנן בתורת כהנים מנין שלא יהיה דבר קודם לתמיד של שחר, תלמוד לומר עליה העולה עד כאן, ותניא בתוספתא דפסחים כל הקדשים שהקריבן קודם לתמיד של שחר וכו' פסולים וכו' עד כאן:
@2 **הא** למדת אם אין עולה כל הנעשה קודם לה פסול, ומזה ישתלשלו דברים רבים שיש בהם חסרון כים, הרי שהביא כבש בן שנתו, ואם היה מקריבו סמוך להבאתו היה כשר, ולצד שאומרים לו עמוד (עד) שיקריב תמיד של שחר הרי זה הפסידו בשהיית שעה אחת, כי מונין שעות לקדשים, כדאיתא בפרק ב' דזבחים (כה:) ובפרק על אלו מומין (בכורות לט:):
@2 **וכן** משכחת לה אם קמץ והקטיר קודם הרי זה פסול, גם משכחת לה שיהיה זמן שלא היה להם כבשים להקריב, בזמן שהיתה ירושלים במצור ואין מציאות לעבודת בית אלהינו להקריב קרבן מהקרבנות הבאים משאר בעלי חיים, והמנחות והקטורת, וצריכין ישראל לתת ממון רב בכבש לצד שאין מציאות להקריב עד שיקדים:
@2 **וכן** תמצא (ב''ק פב:) שהיו משלשלין להם קופה מלאה דינרי זהב בעד כבש אחד, ואין לך חסרון כים גדול מזה, ואולי שאם לא היה העיכוב הנזכר לא היו נותנים כל הפלגה בכבש אחד בכל יום ובפרט מנכסי גבוה:
@2 **לאמר**. אין ידוע למי יאמרו, ואם לדורות, הרי דבר זה נשמע מאומרו צו, כמו שכתבנו בסמוך, ואם לומר לישראל כדי שיכינו העולה ומכשיריה ועצי המערכה, הרי אמר וידבר ה' וגו' לאמר:
@2 **ואולי** כי ציוה עליו שיאמר לאהרן דרשות הרמוזות במכתב אלהים, והדקדוקים אשר יכוין להם הכתוב, כי הפסוק הוא כחזון הסתום, ומה שתמצא שדרשו רבותינו ז''ל אינו אלא לפי מה שקדם אליהם מההלכות שנאמרו למשה בסיני, ואותם ציוה ה' לאמר לאהרן:
@2 **או** ירצה לצד שהכשיר עולים על המזבח, הגם שנפסלו כאמור בדבריהם (בתורת כהנים) בפירוש הכתוב, לזה ציוה שיאמר להם שישתדלו לבל יעלו מן הפסולין, בראותם כי אינם יורדין יחשבו כי אין קפידה כל כך בעלייתם ולא יתנו עליהם לב לשומרם לבל יעלו, לזה ציוה לאמר להם, שישמרו שלא תעלה אלא תורת העולה, פירוש עולה כתורתה וכמשפטה בלא לינה בלא יציאה וכו':
@2 **זאת תורת העולה וגו'**. רבי יהודה דרש (תורת כהנים כאן) ג' מיעוטים, זאת, היא, וה''א של העולה שניה, למעט נשחטה בלילה, ושנשפך דמה, ושיצא דמה חוץ לקלעים, אלו אם עלו ירדו, אבל הלן, וזבח היוצא, והטמא וכו', אם עלו לא ירדו, וכל שאר הפסולין אם עלו לא ירדו, כי תיבת תורת ריבוי הוא:
@2 **וזה** שיעור הכתוב זאת תורת העולה היא העולה, פירוש כל שעלתה על מוקדה וכו', תורת עולה יש לה, ואין לך בה פסול אלא קודם שעלתה, אבל אם עלתה על מוקדה על המזבח, תורת עולה יש לה בכל גוונא, וכל הפסולין טהרם המזבח זולת ג' דברים שמיעט כנזכר, שלא היה לו לומר אלא תורת העולה עולה על מוקדה ואמר זאת, ואמר הא, ואמר היא, למעט כנזכר:
@2 **היא העולה**. כתב רש''י ז''ל מיעט הרובע כו', לא ידעתי למה בחר יותר לפרש הכתוב אליבא דרבי שמעון ולא אליבא דרבי יהודה, שכתב למעט הנשחט בלילה, ושנשפך דמה, ועוד לא דקדק יפה הרב בלשונו, שלא כתב המיעוטים בזאת אלא בהיא העולה, ורבי שמעון מזאת דריש:
@2 **ופשוט** אצלי כי ממיעוט זאת לבד דריש רבי שמעון ולא מהיא העולה, כי אין צריך לרבי שמעון מיעוטים רבים לפרטים שאמר בהם, אם יעלו ירדו, כמו שמיעט רבי יהודה ג' [פרטים] מג' מיעוטים, שאם באנו לומר כן צריכים אנו למיעוטים רבים מלספור, כי רבים הם הפרטים שהזכירם רבי שמעון שעליהם בא המיעוט, אלא ודאי כי ממיעוט אחד מיעט הכל, כל שאין פסולו בקודש אין הקודש מקבלו, וכיון שאין צריך אלא מיעוט אחד וקתני ליה בברייתא (זבחים פד.) תלמוד לומר זאת, מנין לרש''י לומר שדורש היא העולה:
@2 **ותמצא** שאמרו בהוריות (ב:) על מתניתא דקתני נפש אחת וכו', הרי אלו מיעוטין העושה מפי עצמו וכו', ומוקי הש''ס הברייתא כרבי יהודה, ופריך דלמא רבי שמעון היא, ומשני מאן שמעת ליה דדריש מיעוט כהאי רבי יהודה, דתניא זאת תורת העולה היא העולה הרי אלו מיעוטין, הרי כי רבי שמעון לא דריש מיעוט:
@2 **על מוקדה על המזבח**. יתבאר על דרך אומרם בפרק המזבח מקדש (זבחים פה:) כל אלו שאם עלו לא ירדו אם ירדו לא יעלו, אמר עולא לא שנו אלא שלא משלה בהם האור אבל משלה בהם האור יעלו, והגם דאיכא התם מאן דמתני אסיפא דעצמות והגידים והקרנים וכו', הרי מסיק בגמרא דלא נפקא פלוגתא אלא בסיפא, אבל ברישא דרישא האברים והאמורים הפסולים שנתרבו מהעולה שאם עלו לא ירדו ואם ירדו לא יעלו, לכולי עלמא אם שלט בהם האור יעלו הגם שירדו:
@2 **ולזה** אמר הכתוב, כנגד אותם שמשלה בהם האור על מוקדה, וכנגד אותן שעדיין לא משלה בהן האור אלא עלו למזבח אמר על המזבח, וחלקם הכתוב לצד שישתנו בדינם, על מוקדה תעלה הגם שירדה, אבל מה שהוסיף הכתוב לומר על המזבח, דוקא אם עלתה ולא ירדה:
@2 **ולזה** הקדים הכתוב לומר על מוקדה, קודם אומרו על המזבח, ומן הראוי יקדים עליית המזבח כי אינה מוקדה אלא אחר שקדם המזבח, אלא נתכוון לרשום הדרגה ראשונה שבה יחזור הפסול כשר ממש לענין אם ירדו יעלו, ואחר כך אמר הדרגה שנייה שאין בהם הסרת פסול, אלא כל עוד שהם על המזבח כנזכר:
@2 **ובתורת** כהנים נחלקו רבן גמליאל ורבי יהושע, רבן גמליאל סובר על המזבח, כל דבר שראוי למזבח אם עלו לא ירדו, ואפילו נסכים, ורבי יהושע סובר על מוקדה דוקא ולא נסכים וכו', ושבעים פנים לתורה (זוה''ק ח''א מז:):
@2 **ובדרך** רמז תרמוז כל הפרשה על גלות האחרון שאנו בו לנחמנו מעצבון נפשנו, כי כל איש ישראל מאנה הנחם נפשו בראות אורך הגלות, נראה למי דומה, למצרים ת', לבבל ע', לשניהם יחד ת''ע, והן היום אלף ותרע''ב מה אייחל עוד, ולא גלות לבד אלא ענוי מהאומות כי כל גוי וממלכה בבני ישראל יעבודו, ואשר זה יסובב חשוב לא טוב, כי שפת אמת לא הוכרעה בכוננת והאריכה לשון שקר, ובא הצופה ומביט עד סוף כל הדורות קורא הדורות מראש והודיע למשה לזרז לישראל ובראשם בני תורה שפתי כהן אשר תורה יבקשו מפיהו אהרן ובניו להודיע לדורות את הדבר הזה, **זאת תורת העולה**, אמר זאת למעט כל העליות שאין כמוה עולה, וחזר ופירש מי הוא זאת, ואמר **הוא העולה** כבר דכתיב (שה''ש ג) מי זאת עולה מן המדבר. על מוקדה על המזבח הם ב' פרטים שאנו בהם, הא' שאנו בני תורה מה שאין בכל האומות, והב' שאנו מיוסרים בגלות ויסורין ודלות, כנגד התורה אמר **על מוקדה** שנמשלה התורה לאש, וכן תמצא שאמרו ז''ל (תענית ד) האי צורבא מרבנן דרתח אורייתא וכו', וכנגד הגלות וענפיו אמר **על המזבח** כי היסורין מתיחם להם שם מזבח להיותם כפרה, וכן הוא בלשון חכמים (ברכות ה). והודיע הכתוב כי באמצעות ב' דברים תהיה עלייתנו מיועדת בהפלגות המעולות משונות לשבח שבחים אשר לא היה ולא יהיה. וביאר עד מתי יהיו ישראל בגדר ב' דברים אלו, **כל הלילה** שהוא זמן הגלות הנמשל ללילה שומר מה מלילה (ישעי' כא) וכן בפסוק ליני הלילה דרשו ז''ל על הגלות עד הבוקר שהוא זמן שיריק עלינו כבודו ואתא בוקר, והזמן הוא אחר עבור ת''ק לאלף הששי, לפי מה שקדם לנו מדבריהם ז''ל (ב''ר יט) כי יומו של הקב''ה אלף שנה, ומהשכל יהיו ת''ק ראשונה מדת לילה ות''ק שניה מדת יום, והודיע ה' כי עד הבוקר שכשיגמר ת''ק שנה בגלות עד הבוקר שיהיה העליה, ובוקר זה אין אני יודע אם בוקר של אלף הה' או בוקרו של אלף הו' כי באלף הד' גלה כבוד ישראל בעקב''ו, לזה גילה ה' סודו ביד עבדיו הנביאים כי הוא לבוקר ב', והוא אומרו (ישעי' לג) הי' זרועם לבקרים לב' בקרים לבוקר ב' אם לא לבוקר א'. ולזה אמר עד הבוקר הידוע שהוא ב' ולא בוקר הבא ראשון בגלות. ואולי כי לזה רמז הנביא באומרו (ישעי' כא) אמר שומר אתא בוקר וגם לילה פי' הגם שאתא בוקר ראשון לא הועיל ובא גם כן הלילה אחריו כי לא נושענו בו. ואולי כי אלו ישראל היו שלמים היו נגאלים בבוקר ראשון:
@2 **והוא** מה שרמוז בדבריהם שלא נגזר על ישראל גלות אלא יום אחד דכתיב (תהלים כ) יענך ה' ביום צרה פירוש יומו של הקב''ה, ולא נשארים אלא תרע''ב שהם עק''ב שנשארו מאלף הד' ות''ק של אלף הה' הרי תרע''ב ובבוקרו היו נגאלים, ולצד מעשיהם הרעים עכב ויעד בוקר ב', ולזה נתכוון באומרו (ישעי' לג) ה' חננו לך קוינו וגו' פירוש קוינו להיות הגאולה בבוקר א' שלא לעכב עד בוקר ב', אבל על כל פנים היה זרועם לבקרים כשיעברו שנים. ואומרו **ואש המזבח תוקד בו** יודיע הכתוב כי באור בוקר תעשן אף ה' ואש מפיו תאכל על אשר עינונו בני עולה ויסרונו ביסורי נקמה ובפרט בני המערב הפנימי אין לך כוס מר שלא הטעימו תמיד, והוא אומרו ואש המזבח שרמזנו בו בחינת היסורין מהאומות ולא ריחם לבם לאשר הכה ה' זה ימים והשפיל גאון יעקב, ולא נהג בם בחינת דיראון, לומר די ראות עליוני עליונים למטה מטה, אש מזבח זה תוקד בו בנעלם הנעלמים כי הוא המקנא ולובש קנאה ורמז גם כן באומרו ואש המזבח לבחינת עקדת יצחק, גם המזבח יגיד אל בחינת הדין כי יתעוררו הדינים ויתגברו, והוא סוד אומרו **תוקד בו** והבן.
@2 **ולבש הכהן מדו בד** ירצה למדת החסד והרחמים כי יתכנה בשם כהן, הכוונה שגם החסדים יסכימו לנקום נקם, ועיין מה שפירשתי בפרשת וארא וגו' בפסוק (ו' ב') ויאמר אליו אני ה', ואומרו מדו בד יתבאר על דרך אומרם ז''ל כי כל נפש שהורגים האומות מישראל על קידוש שמו ית' הקב''ה רושם מדמו צורת הנהרג ההוא במלבוש ואותו ילבוש יום נקם בלבו, והוא אומרו מדו אשר בו אותם שהם בד שהם ישראל אשר הם (בלק כג ט) עם לבדד ישכון ושורשה בד. גם ירמוז אל האחדות שהם נהרגים על אשר לא יחפצו לשתף שם שמים ודבר אחר ומיחדים שמו יתברך, ואומרו **ומכנסי בד** ירמוז למה שהרגו האומות מהאנשים הנגשים אל ה' המכניסים אמונת ה' ואחדותו בלב ישראל, והם הם יקירי אל עליון אשר אין דבר מפסיק בינו לבינם, והוא מה שדקדק לומר ומכנסי בד לשון הכנסה. בד הוא בחי' האחדות, לאלה אמר על בשרו פירוש אין דבר מפסיק בינם לבין ה', ואמר **בשרו** לשכך את האוזן על דרך אומרו (ירמי' יג) כאשר ידבק האזור אל מתני איש וגו', (במדבר יא א) באזני ה', עיני ה' (תהלים לד), ולצד מה שעשו להצדיקים הללו יחתם גזר דין לאומה רשעה, ואומרו **והרים את הדשן** כנגד מה שהריעו בבחינת היסורין והעינויים אשר צררו אותנו, ואם באת לראות הוא יותר מגלות מצרים, כי גלות מצרים היו משעבדים אותם ומאכילים אותם ומלבישים אותם, וצא ולמד ממה שאמרו ז''ל (מכילתא וילקוט) בפסוק זכרנו את וגו' את הקשואים וגו' חנם היו אוכלים הכל, והן גלות ישמעאלים אשרי מי שלא ראם משעבדים וממררים חיי ישראל, ולא די שלא יתנו שכר אלא עוד שואלים ממנו מדוד והבא, ועוד אדם נגזל במה שיש לו והם תובעים ממנו מה שאין לו, וכוס זה ישקוהו עד שימות, וכנגד זה אמר **והרים** אל מרים ראשי את הדשן אשר תאכל האש אש העמים, כי מצינו שצרת האומות תקרא אש, וצא ולמד מאש בין הכרובים (יחזקאל י) את העולה שהיא האומה הנקראת עולה:
@2 **ואומרו** על המזבח יתבאר על דרך מה שנחלקו רמב''ם (הל' תשובה פ''ו) וראב''ד בענין משפט העובדי כוכבים המענים אומתינו, כי הראב''ד סובר שישפטו על אשר הרעו יותר מהקצוב להיותם בעלי בחירה ורצון. ורמב''ם סובר כי ישפטו גם על העיקר, וכבר כתבתי בפרשת בין הבתרים (לד טו יד) כי האמת הוא שישפטו על הכל בטוב טעם. ומחדש אני דובר כי מהתוספת יוקח ראיה אל העיקר, שאם כונת המענים לקיים מצות ה' היה להם שלא להוסיף וממה שהוסיפו גילו דעתם כי לא למצוה יכוונו. והוא אומרו על המזבח פירוש ביתר על השיעור שהוא לכפרה שקצב ה' להם אותו שיעשו ביותר מהקצוב, **ושמו אצל המזבח** שהוא הקצוב לכפרה וידין ממנו כי לא למצות ה' הם מתכוונים, שהיתר יגלה על בחינת הנגזרה לכפרה אם לה מתכוונים או בשנאה להרע לבד ונמצאים מתחייבים על הכל. או ירצה כי הגם שעדיין לא שלמו ימי גלות יבוא ה' למנין הנותר מהצער הקצוב אשר הוסיפו בני עולה לענות ושמו אצל המזבח להשלים בו כפרה הצריכה אשר קצב ה' בגזרת הגלות:
@2 **עוד** ירצה כי יקריב מעשה הצרות לפני מדת הדין שמתיחסת למזבח כדי לנקום נקם מאויבינו. ואומרו **ופשט** וגו' להיות שבגדים הראשונים הם לעשות משפט בעושי רעתינו ועכשיו בא להטיב להוציאנו מהגלות ולהטיב אותנו, לזה ילבש בגדי בחינת ההטבה, כי לא יעכב קיבוץ גליות עד כלות עושי רשעה אלא תיכף ומיד יקבץ נפוצותינו ויוציא אותנו ממחנה האנשים הרשעים **אל מקום טהור** היא ארץ ישראל הטהורה כי ארץ העמים היא טמאה היא ועפרה ואפילו אוירה (שבת טו) ואין לך מקום שיקרא טהור זולת ארץ הקדושה. גם ירמוז באומרו **מקום טהור** מקומו של הקב''ה הנקרא טהור כביכול, ואומרו **והאש על המזבח** פירוש לא תדמה כי אין צרה לעושי רשעה אלא הרעה ההיא אשר יעשה ה' בהם שפטים בהוציא אותנו מביניהם, לא כן אלא והאש היא בחינת אש המשפט לא תכבה, **וביער עליה הכהן עצים** הם האומות שהם עצים יבשים על דרך אומרו (דברים כ יט) כי האדם עץ וכן אמרו ברבות (בפתיחתא איכה ר') וזה לשונם העצים אלו הגליות ע''כ. ואומרו **בבקר בבקר** ירצה לפי מה שהקדמנו כי זמן הגאולה היה ראוי להיות בבקר ראשון של שנת הת''ק לאלף החמישי ולסיבת העון נתעכב עד בוקר ב', ואמר הכתוב כי לא מפני זה יזכו האומות ולא יבא עליהם מה שהיה צריך לבא עליהם בבוקר ראשון, לו יהיה שישראל לא זכו ליגאל אף על פי כן לא ימלטו האומות מהצרה שהיתה עתידה לבא עליהם אז ויביא ה' עליהם מה שנתחייבו בבוקר ראשון ובוקר ב':
@2 **ואומרו** וערך עליה וגו' יתבאר על דרך אומרם ז''ל (ב''ק פ''ג) הכל לפי המבייש והמתבייש, כי אינו דומה נכבד המבייש נכבד לבזוי המבייש נכבד ואין צריך לומר עבד המבייש את רבו, והוא אומר וערך עליה העולה שהוא האומה הישראלית בכללותה. **והקטיר עליה** פירוש יעריך גם כן בחינת הצדיקים השלמים מובחרי ישראל שלמים שבהם המעלים ריח בשמים על דרך אומרו (תולדות כז כז) ראה ריח בני כריח שדה ותדע כי כל העובר עבירות ריחו נודף לרעה, והמעשה שהובא בדבריהם (קב הישר פ''ז) שהיה עובר אליהו וראה אדם רשע ומנע עצמו מהריח ריחו הרע יותר ממה שהרגיש בעוברו על סרחון נבילה, ובהפך יהיה לאיש צדיק שלם שיעלה ממנו בושם כריח הגן, לזה זכר זכרון עריבתם בלשון הקטרה, והמכוון כי ישפוט בפרטות את אשר הריעו לאנשי בושם:
@2 **עוד** ירצה כי כאשר יעריך ה' את העולה לנקום נקמתה מהמריעים לא יעריכנה בפני עצמה אלא יקטיר עליה המובחרים והשלמים שבאומה שיקראו בשם חלב השלמים שבזה תגדל מעלתה של האומה לנקום נקמה גדולה משונאיה. ואומרו **אש תמיד** וגו' פירוש הגם שיכה ה' בהם מכה רבה לא תכבה אש ותמיד תוקד על המזבח על דרך אומרו (יואל ד) ונקיתי דמם לא נקיתי, עד אבוד רוח הטומאה מן הארץ, והיה ה' למלך על כל הארץ (זכרי' יד):
@15 **והכהן וגו'**. תחתיו מבניו. בפרק התכלת (נא) דרשו שבא לכהן גדול שמת ועדיין לא מינו אחר תחתיו שבנו של מת יביאנה במקומו, והוא אומרו **תחתיו מבניו**. ודרשו מ''ם של מבניו לדרשא אחרת, דתניא שם בניו אלו כהנים הדיוטים, או אינו אלא כהנים גדולים, כשהוא אומר והכהן המשיח תחתיו מבניו הרי כהן גדול אמור מה אני מקיים בניו בהדיוטים, ומסיק שם בגמרא דמאומרו מבניו דורש כן. ובהוריות פרק ג' (יא) אמרו עוד כהן גדול בן כהן גדול טעון משיחה מנלן דכתיב והכהן המשיח תחתיו מבניו נימא קרא והכהן מתחתיו מבניו מאי המשיח וכו' ע''כ. וקשה והלא צריך לומר המשיח ללמד על בניו האמורים בתחלה שהם הדיוטות כמאמר התנא בפרק התכלת. ויש לומר שללמד על בניו האמורים בתחלה שהם הדיוטות שפיר נשמע הגם שלא היה אומר המשיח, כי ב' כתובים בכהן א' למה לי, אלא ודאי שבניו דרישא בהדיוטים בניו דסיפא בגדולים, ולא היה צריך לומר המשיח אלא לדרשא למשוח כהן גדול בן כהן גדול. ועדיין קשה בכתוב למה אמר **תחתיו מבניו** שהיה צריך לומר מבניו תחתיו. ואולי שיכוין להסמיך בניו ליעשה אותה לכוין דרשת פרק התכלת שאם מת כהן גדול ועדיין לא מינו אחר במקומו בנו יביא במקומו, וזה שיעור הכתוב והכהן המשיח תחתיו יעשה, ואם עדיין לא נתמנה, מבניו של מת יעשה אותה, ואם היה אומר הכתוב הכהן המשיח מבניו תחתיו אז תהיה הכוונה שאין חיוב על בנו להביא אלא אם יהיה תחתיו שכן משמע דוקא תחתיו פירוש שנתמנה או שהוא ראוי לעמוד תחתיו, ומאומרו מבניו יעשה משמע כל יורש יביא. ולר''ש שחולק וסובר שאם לא מינו אחר תחתיו באה משל ציבור אמר תחתיו מבניו, לסמוך מבניו ליעשה, לומר כי אין ראוי לשום אדם אחר ליכנס תחת הכהן זולת בנו. אחר שפירשתי זה מצאתי שכן דרשוה בתורת כהנים למבין משמעות הברייתות על נכון:
@28 **אשם הוא**. נחלקו רבנן ורבי אליעזר (ת''כ כאן), רבנן אמרו הוא למעט אם לא שחטו בצפון לעיכובא, ר' אליעזר אומר למעט אם שחטו שלא לשמו והנה לסברת ר' אליעזר ידוייק אשם הוא שחוזר הוא לאשם שצריך שיהיה לשם אשם. והגם שבזבחים (י) מצינו שהקשה ר' יהושע לר' אליעזר וחזר ר' אליעזר ולמד דין זה דשלא לשמו מפסוק (ז) כחטאת כאשם שהשוה אותם הכתוב, אם כן תיבת הוא למה צריכה, ואולי כי זולת הוא הייתי אומר שההקש בא לענין שצריך סמיכה כמו שדרשו חכמים (שם יא) לזה אמר הוא סמך לאשם לומר שצריך לשם אשם, ולצד שנקשה מה שהקשה שם אמר כחטאת כאשם. ולרבנן הוא למעט שחיטה שלא בצפון שהוזכרה בפרשה (פסוק ב) ובא לעכב, והגם שיש להקשות מעין קושיות שהקשה ר' יהושע לר' אליעזר גם לדברי חכמים, כיון שלא חדשו דין זר מהשכל בדרשתם אלא דבר שישנה בכל הקרבנות, וגם הוזכר בפירוש, אלא שמפסוק א' הייתי אומר שאינו מעכב, יכולין לדרוש הוא שבא לעכובא מה שאין כן ר' אליעזר שהוליד דין חדש שאין לו דמיון, לזה הוקשה כל הקשיות הרשומות שם:
@32 **וכל מנחה וגו'**. אמר הכתוב זכרון ה' מנחות למעט ה' דברים א' שלא יחלקו בני אהרן פירוש בית אב זבחים כנגד מנחות אלא כל אחד יטול חלקו במנחה. ב' שלא יחלקו עופות כנגד מנחות הגם שישנם בהשוואה בענין אחד שמצינו שהעוף בא בדלות והמנחה קמה תחתיהם בדלי דלות. ג' שלא יחלקו עופות כנגד זבחים הגם ששניהם מיני דמים. ד' שלא יחלקו מנחות כנגד מנחות הגם שהם מיני קמחים. ה' שלא יחלקו אפילו מחבת כנגד מחבת ומרחשת כנגד מרחשת הגם שמעשיהם שוים, והגם שהמעוטים הם מנחות, דרשום באם אינו ענין. אלא שראיתי לרמב''ם (הל' מעשה קרבנות פ''י טו) שכתב באופן אחר, כי ממה שחלק הכתוב בין מנחות האפויות ומנחת הסולת שהרי באפויות הוא אומר כל המנחה לכהן המקריב וגו' ובמנחת סולת הוא אומר וכל מנחה לכל בני אהרן וגו', לומר לך שאפילו מנחת סולת שהיה עולה על הדעת שיחלקוה מנחה כנגד מנחה לצד שאם יחלקוה ביניהם מגיע לזה מלא כפו וכו' שאינו דאוי לא ללוש ולא לאפות אף על פי כן לכל בני אהרן יחלקוה בפני עצמה, מכאן אמרו חכמים אין חולקין מנחה כנגד מנחה ע''כ. נמצאת אומר לדבריו שהלימוד הוא מאומרו לכל בני אהרן במנחת סולת מזה אנו לומדים לכל המנחות, ומן הברייתא אינו נשמע כן:
@32 **ועוד** דקדק הרב בלשונו שהלימוד הוא ממה שחלקם הכתוב, משמע שאם לא חלקם לא היינו שומעים זה, ודלא כהברייתא. ואולי כי סובר רמב''ם כי ממה שחלק הכתוב בין מנחות האפויות וכו' בזה גילה לנו הכתוב כוונתו שבא לומר שלא יחלקו ביניהם אחת כנגד אחת אפילו במנחת סולת, ומזה למדו לכל המנחות, כי במרחשת ומחבת לא הוזכר בה חילוק לכל אלא שלא יטלוה זולת בית אב של אותו יום, ומנין אתה אומר שלא יטלו מחבת כנגד מרחשת אם לא הוזכר בה סדר חלוקתה אם לכולם יחד אם לאחד מהם. ומה שלמדו כל הה' פרטים מה' מיעוטים אסמכתא היא, ולעולם עיקר לימודם הוא ממה שחלק הכתוב. ומעתה צריך לדעת למה פרט הכתוב כל המנחות כיון שלימודנו הוא ממה שחלק לא היה לו לומר אלא כל מנחה לכהן המקריב וגו' וכל מנחה חרבה לכל בני וגו'. ואולי שאחר שירד הכתוב לפרט מאפה וחרבה חש שיטעה אדם לחלק ביניהם לבין שאר מנחות, גם מצינו שדרשו ז''ל (תו''כ מנחות סג) וכל נעשה במרחשת ועל מחבת שעל שם כליין נקראו ונפקה מינה האומר הרי עלי מרחשת כלי שרת נדר, והוא דבר שנחלקו בו (שם) בית שמאי ובית הלל לזה אמר הכתוב **וכל נעשה במרחשת ועל מחבת** לגלות לך שעל שם כליין נקראו, ואומרו **אשר תאפה בתנור** דרש גם כן רבי יוסי ב''ר יהודה שבאה ללמוד על עצמו מהסמיכות של כל נעשה במרחשת ועל מחבת מה מרחשת ומחבת הם ב' גם מאפה תנור הם ב', ולא יביא מחצה חלות ומחצה רקיקין, וגם ללמד על מרחשת ומחבת בא לומר מה תנור כלי גם מחבת ומרחשת כלי כאמור שם בתורת כהנים. ונשאר אומר כל מנחה בלולה בשמן וחרבה למה הוצרך לומר ב':
@32 **ונראה** כי כוונת רבי יוסי ב''ר יהודה שלמד כל מנחת מאפה שהוא ב' מיני מנחות לא למדה אלא ממה שאמר הכתוב ב' פעמים כל אחרי כן והם ב' ב', ולזה דייק בלשונו תלמוד לומר וכל מנחה וכל נעשה וגו' וכל מנחה בלולה וגו' מה כל וכל האמורים למטה ב' מינים וכו', ולזה אם היה אומר הכתוב וכל מנחה בלולה לבד או כל מנחה חרבה לבד אין מקום ללמוד ויש לבעל הדין לחלוק ולומר כל מנחה חרבה תוכיח שאמר כל ואין בה אלא מין אחד אף כל מאפה תנור מין אחד לזה הוצרך לומר כל האמור בכתוב:
@43 **והנפש אשר וגו' וטומאתו וגו'**. פסוק זה ושלאחריו בטומאת הגוף פירשוהו בתורת כהנים ובזבחים דף מ''ג אמרו כל קרא שלא פירשו רבי יצחק בר אבדימי וכו' לא מפרשא הכי אמר רבי יצחק בר אבדימי הואיל ופתח הכתוב בלשון נקבה וסיים בלשון נקבה ולשון זכר באמצע בטומאת הגוף הכתוב מדבר ע''כ. ופירש''י הואיל וכו' פירוש פסוק נפש כי תגע שהוא פסוק ב' ושם בהכרח לומר שעל טומאת הגוף הוא אומר הגם ששינה באמצע גם בפסוק ראשון והנפש אל תתמה עליו שדיבר תחלה לשון נקבה והנפש ולבסוף ונכרתה ובאמצע וטומאתו שאין הכוונה על הבשר אלא על הגוף ע''כ. דבריו ז''ל הועילו שלא להכריח ממה ששינה באמצע לומר שנתכוון לומר שבטומאת בשר הוא אומר, אבל להכריח שעל טומאת הגוף הוא אומר הוא ממשמעות הכתוב, שנראה שכבר נגמרו הלכות טומאת בשר כמו שפירש''י שם בזבחים. ועוד בתורת כהנים למדו גזירה שוה טומאתו טומאתו האמורה בביאת מקדש (בפ' חוקת), אלא נתתי לבי למה שינה הכתוב בב' פסוקים אלו, בפסוק אחד שינה לכתוב וטומאתו וסמך ללמוד בגזירה שוה והיה לו לכתוב וטומאתה ולא היינו צריכין לגזירה שוה, גם בפסוק ב' למה לא אמר לשון ישר כל הכתוב בסדר אחד:
@43 **ונראה** כי טעם אומרו **וטומאתו עליו** בא להעיר ענין אחר, שהגם שעברו ז' ימי טומאה לטומאת מת או הערב שמש לטומאת שרץ כל עוד שלא טבל הרי הוא בטומאתו, ויש לך לדעת כי טומאה זו אינה בפנימיות הנפש אלא מסוה הטומאה המסכך על הגוף מבחוץ ולא בפנים, ולצד זה הוא שמועיל לו טבילה להסיר מסוכת הטומאה מה שלא יועיל לו במשך ימי הטומאה שהטומאה גם בפנים, וזה שיעור הכתוב **נפש אשר תאכל** וגו' **וטומאתו עליו** פירוש לא מבעיא וטומאתה עליה שהוא במשך ז' לטומאת מת ובמשך יום מגעו לטומאת שרץ, אלא אפילו טומאתו של גוף לבד היינו שעבר עליו שבעה ימי טומאה ואינו חסר אלא טבילה להעביר מעל גופו אפילו הכי **ונכרתה**. וטעם אומרו בפסוק ב' לשון זכר באמצע הגם שאין טעות בדבר לא היה לו לומר אלא סדר אחד בכל הכתוב. ונראה כי טעם אומרו **ונפש כי תגע** לשון נקבה ולא אמר איש כי יגע לשון זכר, שנתכוון לומר שצריך שיגע לדעתו ולא בהעלם, שאינו חייב כרת אלא בידיעת טומאה, וגם אומרו בפסוק אחד והנפש אשר תאכל שהיתה אכילת בשר בידיעה, כי הנפש יורה אל ההרגש ולמניעת ההעלמות, ולטעם זה תמצא שאמר בפרשת השגגות (לעיל ד וה') ונפש לומר טעם המחייב חטאת ואשם על השוגג הוא לצד היותה נפש שהיא בחינת ההערה והידיעה ושגגה, לזה תתחייב קרבן, ולעולם שם נפש יורה על בחינת שלילת ההתעלמות, ולזה אמר בב' כתובים נפש כי תגע הרי ידיעת הנגיעה, והנפש אשר תאכל הרי ידיעת המאכל, ומעתה אין מקום לקושיא למה אמר לשון זכר באמצע, שאין צורך לשנות סדר הרגיל לומר על העושה לשון זכר, וטעם אומרו ונכרתה הנפש ההיא, בא גם כן להשמיענו חידוש שגם נפש החוטאת תמות ולא גוף לבד:
@43 **וחוץ** מדרכם ז''ל נראה ליישב כפל הכתובים על דרך מה שאמרו בזבחים דף ק''ו במשנה, הטמא שאכל בין קודש טמא בין קודש טהור חייב ורבי יוסי הגלילי אומר טמא שאכל טמא פטור, ואמרו בגמרא (שם קח) כל היכי דנטמא הגוף ואחר כך נטמא הבשר דכולי עלמא לא פליגי דחייב, ולזה אמר ב' כתובים, האחד אשר תאכל בשר מזבח השלמים זה טמא האוכל בשר שלמים טהור, והב' אמר ואכל מבשר זבח וגו' זה כנגד טמא האוכל מבשר שלמים שנטמא. ואולי כי לזה דקדק הכתוב לומר בפסוק אחד **תאכל בשר מזבח השלמים**, פסוק הבשר הוא מזבח השלמים שהוא עדיין במדרגתו שלא נטמא, והב' אמר **מבשר זבח השלמים** פירוש ממין בשר שלמים הגם שעכשיו אינו בשר שלמים שבא בו יעוד האכילה, והוא אומרו מבשר ששם זבח שלמים עליו, כי לא קשר הבשר עם זכרון זבח השלמים לרמון כי אינו בגדר סתם זבח שלמים הטהור ודו''ק ולא יפנה לבבך לטעות אחר המ''ם באופן אחר:
@48 **מן הבהמה**. דרשו ז''ל בתורת כהנים לרבות כלאים מתיש ורחל או להפך, ומאומרו כל חלב ריבה כוי שהוא הבא מתיש וצביה, ועיין מה שכתבתי בחבורי פרי תואר על טור יורה דעה סימן טז:
@48 **כל אוכל חלב**. בתורת כהנים דרשו לרבות חלב בהמת חולין, שלא תטעה לומר אשר יקריב ממנה אשה לה' אמר הכתוב דוקא חלב קדשים תלמוד לומר כל חלב, ורבוי זה אם אינו ענין לאוכלין תנהו ענין לנאכלין. וקשה לי איך נטעה לומר דוקא חלב קדשים והלא אמר וחלב נבלה יעשה לכל מלאכה אימורי קדשים מי מותרים להדיוט, והלא אמרו בכיצד צולין דף פ''ב נשחטה ונמצאת טריפה הרי זה תצא לבית השרפה מדכתיב (לעיל ו כג) בקדש באש תשרף לימד על כל פסולים שבקדש בשרפה, ואם כן מאומרו וחלב נבלה וחלב טריפה יעשה לכל מלאכה אתה יודע כי לא של קדשים לבד אסר הכתוב, ולא היה צריך לומר כל אוכל, ויש לומר דעיקר לימוד התנא מכל אוכל חלב הוא על חיוב כרת, וזולת כל הגם שהייתי למד מפסוק יעשה לכל מלאכה ואכול לא תאכלוהו, הייתי אומר לאו דוקא, ולא כרת, ולא בא הכרת אלא על חלב קדשים. ואומרו שור כבש ועז דרשו בתורת כהנים שבא למעט בהמה טמאה וחיה ועוף. ובחולין דף קי''ו אמר ליה רב מרי לרב זביד אי אליה אקרי חלב תתסר באכילה אמר ליה עליך אמר קרא חלב שור וכשב ועז דבר השוה בשור וכשב ועז ע''כ. וקשה והלא אצטריכו שור וכשב ועז למעט בהמה טמאה ועוף וחיה שהיו באים בקל וחומר לאסור כאמור שם בתורת כהנים תלמוד לומר שור וכשב ועז. ואולי כי שלשה אלה ממועטים הם מאומרו אשר יקריב ממנה אשה לה' יצתה חיה, יצתה בהמה טמאה, יצא עוף שאין כולו נקרב. או שאחר שמיעט הכתוב בהמה טמאה וחיה הרי גילה הכ' שאין לדון קל וחומר מדם שהרי בהמה טמאה וחיה יוכיחו. וכן תמצא שכתב רש''י בחולין (קיז) בפירוש המשנה שאמרה אינו נוהג אלא בטהורים דכתיב אשר יקריב ממנה אשה לה', ועיין בפסוק שאחר זה:
@48 **מן הבהמה**. דרשו בתורת כהנים להביא חולין בעלי מומין, שלא תאמר חולין דומיא דקדשים תלמוד לומר מן הבהמה לרבות אפילו בעלי מומין. והגם שאסר הכתוב בפירוש חלב נבילה וטריפה הגם שאסורים למזבח, בשלמא טריפה נוכל לומר כדעת רמב''ם (איסורי מזבח פ''ב) שאין בה איסור למזבח מן התורה אלא משום (מלאכי א) הקריבהו נא לפחתך, והגם שבתורת כהנים (סימן א פ''ב) דרשו לאסור מן הכתוב אינו אלא אסמכתא וכמו שכתב שם הכסף משנה, אלא נבילה פיסול המזבח הוא כי ושחט כתיב בכל הקרבנות. ויש לומר שלענין כרת מחזר התנא וכמו שכתבתי למעלה:
@48 **אשר יקריב**. אמרו בתורת כהנים מה תלמוד לומר אשר יקריב, חלב שכמותו כשר ליקרב על גבי המזבח, יצא חלב דפנות שאין כשר ליקרב ע''כ. הנה לסברא זו שהוציא מיעוט בהמה טמאה וחיה ועוף מאומרו שור וכשב ועז לא היה צריך לומר אשר יקריב, והוצרך למעט חלב דפנות. וקשה לרב זביד שדרש שור וכשב ועז לאליה שמותרת, ואשר יקריב למעט בהמה טמאה וחיה ועוף מנין להתיר חלב דפנות, גם לתנא שדרש שור וכשב ועז למעט טמאה וחיה ועוף היתר האליה מנא ליה ויש לומר לרב זביד אומרו אשר יקריב ימעט בהמה חיה ועוף וכו' גם חלב דפנות, כי כל שאינו קרב לה' הרי הוא בכלל המיעוט, ותנא דתורת כהנים גם כן ימעט גם כן מאומרו שור וכשב ועז את האליה, שאם לא בא הכתוב אלא לבהמה טמאה וחיה ועוף לא היה לו לומר אלא שור ושה, וכשנתמעט דבר שישנו באיסור דם תו לא עבדינן קל וחומר, וכלום למה איצטריך למעט משום שהייתי דן קל וחומר מדם, במיעוט אחד שיתמעט בהמה טמאה או חיה או עוף נסתר קל וחומר, ולא איצטריך אלא ללמד על האליה שאינה שוה בכולן שמותרת אלא שעדיין אין הדעת מתישבת בזה, למה יחלוק רב זביד על תנא דתורת כהנים דממעט טמאה וחיה ועוף משור וכשב ועז והוא ימעטם מאשר יקריב ממנה לה'. ועוד הרי התנא גילה דעתו כי אומרו אשר יקריב וגו' לא יספיק לדרוש ממנו למעט בהמה טמאה וחיה ועוף וחלב הדפנות ממה שחלקם לב' מיעוטים. אשר על כן הנכון בעיני הוא כי גם לכולי עלמא מיעוט בהמה טמאה חיה ועוף אינו אלא מאומרו שור וכשב ועז, ודרשה זו היתה צודקת הגם שהיה אומר שור ושה, וממה שפרט כשב ועז למעט האליה, ואומר אשר יקריב בא למעט חלב הדפנות, ולא כמו שפירש''י שכתבתי למעלה:
@60 **זאת התורה לעולה**. לא נודע כוונת פסוק זה. ובתורת כהנים דרשו לומר לך מה מילואים נאמרו כללותיהן ודקדוקיהן מסיני אף כל נאמרו וכו'. וכבר כתבתי במקומות אחרים (ריש פ' משפטים) מה שיש להעיר בדבר זה. עוד דרשו ז''ל (תו''כ זבחים צז:) ללמד על הזבחים כולן שטעונין סכין כעולה, וללמד על שלמי ציבור שנאכלין לזכרי כהונה כמנחה וכו'. ובדרך רמז נראה על דרך אומרם במנחות (קי.) אמר ריש לקיש מאי דכתיב זאת התורה וגו' כל העוסק בתורת עולה כאילו הקריב כו' ע''כ, גם אנו נאמר בדרך זה:
@60 **וקודם** אקדים דברי רז''ל אנשי אמת שונים בש''ע נהורים אשר אמרו כי תכלית עסק התורה הוא לברר ניצוצי הקדושה אשר נפלו ואשר נאנסו מהקדושה ולהחזירם ביחוד שלם לכמות שהיו, והם שני בחינות, האחד ניצוצי הקדושה שירדו בעולם התהו לסיבה ידועה לו והמושג ליודעי דעת יספיק לטעם נכון, והשני הם נפשות העשוקות אשר עשק אדם בליעל מאדם הראשון בחטאו אשר שלל שלל רב, כידוע הפלגת הנשמות אשר הרבה לעשוק, ואין לך דבר שפוקד עליו להוציא בולעו מפיו זולת אמצעות עסק התורה יעשה כל דבר עיקר. יעלה ניצוצי הקדושה שנפלו קודם עולם התיקון, ויוציא מס''מ בולעו מפיו ומפוצצו וממחה כוחו עד אשר יקיא חיל בלע, והוא מאמרם ז''ל (קדושין ל:) אם פגע וכו' אם אבן הוא נימוח ואם ברזל מתפוצץ ובפסוק זה גילה הכתוב פלאי התורה ותעצומיה, ואמר **זאת התורה** תועלותיה אשר תסובב קריאתה, **לעולה** פירוש שבאמצעותה תתעלה השכינה שהיא בחינת כנסת ישראל, ב' **למנחה** תיבה זו סובלת כמה פירושים וכולן צודקין, לשון מנוחה ולשון נחת, ולשון הנחה, וזה הפירוש הוא סוד (חולין צא:) עלי יניח צדיק זה את ראשו, והוא סוד (ב''ר פ''י) באה שבת באה מנוחה כי יניח עליה צדיק יסוד עולם, והוא סוד (שה''ש ב') שמאלו תחת לראשי וימינו תחבקני והבן:
@60 **לחטאת** ולאשם הם שני בחינות הברורין, האחד חלקי הקדושה שירדו למטה ממדרגתם בתחילה בעולם התהו כנגדם אמר לחטאת, והשניה חלקי הנשמות שנעשקו מאדם בחטאו כנגדם אמר **לאשם**, כי התורה תועיל לשני בחינות אלו לבררם ממקום ירידתם. ולא בירור לבד אלא גם יכוננם במקום שנחסרו ממנו, והוא אומרו **ולמלואים** למלאותם במקומם, זה כנגד ניצוצות שירדו וכנגד חלקי נשמות שאנס ס''מ מאדם הראשון אמר **ולזבח השלמים**, על דרך אומרו (תהלים נ) זובח תודה יכבדנני ודרשו ז''ל (סנהדרין עג:) זה הזובח יצרו. והזביחה הוא שינצחהו ובבחינת הנצחון הוא בורר ממנו בחינת הטוב אשר אנס מאדם הראשון. והנה בחינה זו היא מעלה גדולה אשר יתעצם לזבוח יצרו כמעשה דוד שאמר (תהלים קט) ולבי חלל בקרבי ודבר זה עושה פעולה גדולה בבחינה שאנו משתדלים עליה, ואין מציאות להשגה זו זולת באמצעות התורה כאומרם (קדושין ל:) אם פגע בך מנוול זה משכהו לבית המדרש, וכן אמרו (שם) אמר הקב''ה בראתי לכם יצר הרע בראתי לו תבלין שהיא התורה:
@60 **עוד** ירמוז באומרו **ולזבח השלמים** כי תכלית הבירור יהיה באמצעות הזבח דכתיב (ישעי' לד) כי זבח לה' בבצרה, ואמרו ז''ל עתיד הקב''ה לשחוט את השטן, ופירוש שחיטה זו היא שיסיר ממנו בחינה המחייהו שהוא ניצוץ הקדושה ובזה השלמים נשלמו כל הבירורים, והודיע הכתוב כי גם הדבר הזה יושג באמצעות עסק התורה כי בזכות עסק התורה שעוסקים הצדיקים בעולם הזה יהיה הדבר, ולזה רמזו ז''ל (שם) בדבריהם כי השחיטה הלז תהיה על זה הדרך הקב''ה מצד אחד וכל הצדיקים תופסין הסכין מצד אחר לזבוח זבח ההוא כי בכחם היה המושג, הא למדת זאת התורה לכל הדברים הנפלאים, **לעולה למנחה** כנגד העלאת השכינה ויחודה עם הקב''ה, **לחטאת ולאשם** לברר ב' בחינות הברורים שהם עיקר העולם, **ולמלואים ולזבח השלמים** ליחד ניצוצות היורדות למלאותם במקומם, ולזבוח יצרו זביחה שאין אחריה קיום, גם יעמוד חי לפני ה' לשלוח יד במבקשי רעתו לזבוח זבח, והיה ה' למלך וגו' יהיה ה' אחד ושמו אחד, והוא אומרו השלמים פירוש שנשלמו כל בחינות הקדושה ונתיחדו יחד. ואומרו **אשר צוה ה'** וגו' חוזר לסיבה שהיא התורה שהזכיר בראש הפסוק, כאילו אמר זאת התורה אשר צוה ה' וגו' שצריכין ללמוד התורה על מנת כן לא לתכלית אחר זולתו, ואומרו **ביום צוותו** כי דבר זה נאמר להם במעמד הר סיני דכתיב במדבר סיני, ואמר **להקריב את קרבניהם** כאן רמן בתוספת ביאור מה שפירשתי שמקריבין כל חלקי הקדושה שהם מיוחסים לישראל שהם הם הדרגת הקדושה וכל חלקי הקדושה להם יתיחסו ובאמצעות התורה יקריבו את קרבניהם ויתיחדו כל בחינות הקדושה כנזכר למעלה:
@63 **קח** את אהרן וגו'. פרשה זו נאמרה קודם הקמת המשכן, וטעם שנאמרה כאן, לומר לך שקדמו כל משפטי הקרבנות ופרטיהן ודקדוקיהן קודם מילואיו, כי לעשות כולן נתכהנו הוא ובניו, ולא נתכהן עד שלמדו משה כל פרטי דיני כל הקרבנות וקיים וקבל עליו לעשות ככל הכתוב ואז אמר לו קח את אהרן שעל מנת כן נתכהן, ועוד שזולת זה משכחת שיביא אדם מישראל קרבן מיד בקרבתו לפני ה' ולא ידע מה לעשות:
@65 **ותקהל העדה וגו'**. אולי כי בראותם מעשה משה שלקח אהרן ובניו והבגדים וגו' נקהלו מעצמן. או ירצה להודיע שהחזיקם המקום לכל ישראל בפתח אהל מועד, כמו שדרשו ז''ל (ויק''ר פסוק שלפני זה) בפרשת הקהל וגו', וכאן יודיע הכתוב שכן היה:
@66 **ויאמר** וגו' זה הדבר וגו'. אמר כן להודיעם לבל יערערו על הדבר כקרח וכעדתו בחושבם כי מלבו ומרצונו היה עושה. ומעתה אין טענה לקרח כי שוגג היה שהרי הודיעו בשעת מעשה כי זה הדבר הוא מצות ה' ולא מלבו ומרצונו של משה. עוד ירצה על דרך אומרם ז''ל (שמו''ר פ''ב) כי משה מלך היה דכתיב (ברכה לג) ויהי בישורון מלך ותנן (כתובות יז.) מלך שמחל על כבודו אין כבודו מחול, והנה משה היה עושה מעשים שאסור לעשותם אפילו עבד עברי לאדונו לרחוץ אותם במים וכו' כל גופם וכל סדר המעשה, ואין לך זלזול גדול מזה, אשר על כן הקדים לומר **זה הדבר אשר צוה ה'** מפי ה' נאמר לי לעשותו, ודוקא זה ולא אחר כי המלך אסור לעשות כן הגם שיחפוץ למחול, כי דוקא זה הדבר לצד שהפה שאסר מלך שלא ימחול על כבודו הוא שהתיר וצוה לי לעשות. עוד ירצה על דרך מה שאמרו ז''ל בתורת כהנים בפסוק וירחץ אותם במים באותה שעה זכו בקידוש ידים ורגלים ובטבילת יום הכפורים ע''כ. והוא אומרו זה הדבר **אשר צוה ה' לעשות** לדורות, כי בזה יזכו בקידוש ידים ורגלים וטבילה ביום הכיפורים לדורות:
@71 **וימשח את המשכן וגו'**. הטעם שהפסיק בין לבישת אהרן למשיחתו במשיחת המשכן וכליו, לצד שמצינו שצוה ה' במשיחת המשכן וכליו קודם למשיחת אהרן כרשום בפרשת פקודי (מ' ט'), ומן הראוי היה להקדים משיחת המשכן גם ללבישת בגדי אהרן כרשום שם, וטעם שלא עשה כן לצד שדקדק מאמר ה' כאן בפרשה זו (פסוק ב') שאמר לו קח את אהרן וגו' ואת שמן המשחה וגו', ואם משיחת המשכן קודמת גם ללבישת בגדי אהרן היה לו לומר קח את שמן המשחה שהוא דבר שיעשה ממנו המצוה הראשונה שהיא משיחת המשכן ואין מקום לטעות מאומרו קח את שמן המשחה ראשונה שימשח אהרן קודם לבישת בגדיו, שהרי כבר אמר והלבשת את אהרן וגו' ומשחת אותו, אלא ודאי שכוונתו הוא להקדים לבישת הבגדים קודם למשיחת המשכן, ומה שהקדים משיחת משכן בפרשת פקודי ללבישת בגדי אהרן ולמשיחתו אינו אלא למשיחתו דוקא, אלא לצד שלא רצה הכתוב להפסיק בין מצות הבגדים למצות המשיחה של אהרן לזה אמר כל דיני אהרן יחד, ולעולם לא תקדים משיחת המשכן וכליו אלא למשיחת אהרן ולא לבגדים כמו שגילה כאן כנזכר:
@89 **על העולה**. שלא היה דבר מפסיק. ואולי שלא שהה עד שאכלה האש את העולה אלא ועדיין העולה קיימת:
@92 **כאשר צויתי**. פירוש על האכילה צוה כבר שיאכלוה ועתה הוא מצוה על המקום, הא למדת מצוה על האכילה, ומצוה על המקום ואם ירצה שלא לאכול הרי זה בטל המצוה, ואם ירצה לאכול חוץ מהמקום הרי זה בטל המצוה. ואומרו **לאמר** פירוש לא שצוה מעצמו אלא ממה שנאמר לו מפי השכינה:
@92 **חסלת פרשת צו**
